10	  <script>
11	    (function() {
12	      try {
13	        var params = new URLSearchParams(window.location.search);
14	        if (params.get('lang') === 'en') {
15	          localStorage.removeItem('portalLang');
16	          return;
17	        }
18	        var pref = localStorage.getItem('portalLang');
19	        if (pref === 'fr' || pref === 'es') {
20	          var path = window.location.pathname;
21	          var isAlreadyLocalized = path.indexOf('/fr/') !== -1 || path.indexOf('/es/') !== -1 ||
22	                                   (document.documentElement && document.documentElement.lang && document.documentElement.lang !== 'en');
23	          if (!isAlreadyLocalized) {
24	            var pathParts = path.split('/');
25	            var page = pathParts[pathParts.length - 1] || 'index.html';
26	            window.location.replace(pref + '/' + page + window.location.search + window.location.hash);
27	          }
28	        }
29	      } catch (e) {}
30	    })();
