1252	  <script type="module">
1253	    // Pretext-powered text reflow for metric tiles and card titles
1254	    const { prepare, layout } = window.Pretext;
1255	    await document.fonts.ready;
1256	
1257	    const pretextElements = document.querySelectorAll('[data-pretext]');
1258	    const prepared = new Map();
1259	
1260	    for (const el of pretextElements) {
1261	      const font = getComputedStyle(el).font;
1262	      prepared.set(el, prepare(el.textContent, font));
1263	    }
1264	
1265	    function relayout() {
1266	      for (const [el, handle] of prepared) {
1267	        const lineHeight = parseFloat(getComputedStyle(el).lineHeight);
1268	        const { height } = layout(handle, el.clientWidth, lineHeight);
1269	        el.style.height = `${height}px`;
1270	      }
1271	    }
1272	
1273	    const ro = new ResizeObserver(() => relayout());
1274	    ro.observe(document.body);
1275	    relayout();
1276	
1277	    for (const el of pretextElements) {
1278	      if (el.contentEditable === 'true') {
1279	        new MutationObserver(() => {
1280	          const font = getComputedStyle(el).font;
1281	          prepared.set(el, prepare(el.textContent, font));
1282	          relayout();
1283	        }).observe(el, { characterData: true, subtree: true, childList: true });
1284	      }
1285	    }
1286	  </script>
